    visited = [[False]*cols for _ in range(rows)]

    def dfs(r, c):
        stack = [(r,c)]
        comp = []
        while stack:
            cr, cc = stack.pop()
            if visited[cr][cc]: continue
            visited[cr][cc] = True
            comp.append((cr, cc))
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = cr+dr, cc+dc
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == 3:
                    stack.append((nr, nc))
        return comp

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 3 and not visited[r][c]:
                comp = dfs(r, c)
                if comp:
                    components.append(comp)

    # Find holes: 2s or 0s completely surrounded by a component's bounding box
    result = {}
    for i, comp in enumerate(components):
        rows_in = sorted([r for r, c in comp])
        cols_in = sorted([c for r, c in comp])
        rmin, rmax = rows_in[0], rows_in[-1]+1
        cmin, cmax = cols_in[0], cols_in[-1]+1

        # Get boundary cells (cells in box but not in component)
